def test_day_8_branching_surface_is_complete_and_has_no_future_api():
    branching = _public_surface(STARTER, "branching")
    assert set(branching) == {
        "BranchOutcome",
        "KvPrefixGenerator",
        "PrefixReuse",
        "run_branch",
        "select_branch",
    }
    assert {name for name, *_ in branching["KvPrefixGenerator"]} == {
        "fork",
        "restore_checkpoint",
        "reuse",
        "save_checkpoint",
    }
    starter_class = next(
        node
        for node in _tree(STARTER, "branching").body
        if isinstance(node, ast.ClassDef) and node.name == "KvPrefixGenerator"
    )
    reference_class = next(
        node
        for node in _tree(REFSOL, "branching").body
        if isinstance(node, ast.ClassDef) and node.name == "KvPrefixGenerator"
    )
    starter_call = next(
        node
        for node in starter_class.body
        if isinstance(node, ast.FunctionDef) and node.name == "__call__"
    )
    reference_call = next(
        node
        for node in reference_class.body
        if isinstance(node, ast.FunctionDef) and node.name == "__call__"
    )
    assert (ast.unparse(starter_call.args), ast.unparse(starter_call.returns)) == (
        ast.unparse(reference_call.args),
        ast.unparse(reference_call.returns),
    )
    assert _is_stub(starter_call.body) and not _is_stub(reference_call.body)
    source = "\n".join(
        path.read_text(encoding="utf-8") for path in STARTER.glob("*.py")
    )
    for future_name in ("Session", "reconcile", "radix"):
        assert future_name not in source


