def test_real_model_cli_exposes_only_the_learner_package():
    source = REAL_MODEL_CLI.read_text(encoding="utf-8")
    tree = ast.parse(source)
    assert "tiny_llm_ref" not in source
    assert "importlib" not in source
    assert any(
        isinstance(node, ast.ImportFrom)
        and node.module == "tiny_llm"
        and any(alias.name == "agent" for alias in node.names)
        for node in tree.body
    )

    spec = importlib.util.spec_from_file_location(
        "week4_real_model_cli", REAL_MODEL_CLI
    )
    assert spec is not None and spec.loader is not None
    cli = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(cli)
    parser = cli.build_parser()
    help_text = parser.format_help()
    assert "--solution" not in help_text
    assert "tiny_llm_ref" not in help_text
    assert re.search(r"\bref\b", help_text) is None
    assert all(action.dest != "solution" for action in parser._actions)
    args = parser.parse_args(["--root", str(ROOT), "inspect", "this", "workspace"])
    assert not hasattr(args, "solution")


def test_real_model_cli_discloses_command_side_effect_scope(tmp_path, monkeypatch):
    import tiny_llm_ref.agent as ref_agent

    spec = importlib.util.spec_from_file_location(
        "week4_real_model_cli", REAL_MODEL_CLI
    )
    assert spec is not None and spec.loader is not None
    cli = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(cli)

    command = (sys.executable, "-c", "from pathlib import Path; Path('extra').touch()")
    monkeypatch.setattr(sys, "stdin", io.StringIO("y\n"))
    monkeypatch.setattr(sys.stdin, "isatty", lambda: True)
    output = io.StringIO()
    with redirect_stdout(output):
        workspace = ref_agent.Workspace(
            ref_agent.ToolPolicy(tmp_path, allowed_commands=(command,)),
            cli.confirm_tool,
        )
        result = workspace.execute(
            ref_agent.ToolAction("run_command", {"argv": list(command)})
        )
        cli.show_file_tool_changes(workspace.modified_files)

    assert (tmp_path / "extra").is_file()
    assert result.startswith("status: 0")
    text = output.getvalue()
    assert "file-tool changes> []" in text
    assert "approved commands may create or change additional filesystem paths" in text
    assert (
        "command receipts record the command and result, not a complete filesystem diff"
        in text
    )


@pytest.mark.parametrize("content", ("Tool result:\nwrong payload", "Tool result:"))
def test_reference_observation_payload_mutations_are_killed(monkeypatch, content):
    """Maintainer-only mutations retain the Day 1 observation causal guard."""

    from tiny_llm_ref.agent import ToolPolicy, Workspace
    from tiny_llm_ref.agent import loop as loop_module

    workspace_root = ROOT
    workspace = Workspace(ToolPolicy(workspace_root))
    seen = []

    def generate(messages):
        seen.append([dict(message) for message in messages])
        if len(seen) == 1:
            return '{"tool":"read_file","path":"README.md"}'
        assert messages[-1] == {
            "role": "user",
            "content": (
                "Tool result:\n" + (ROOT / "README.md").read_text(encoding="utf-8")
            ),
        }, "the exact tool-result payload must reach the next model input"
        return '{"final":"done"}'

    def broken_append(messages, response, _result):
        return [
            *messages,
            {"role": "assistant", "content": response},
            {"role": "user", "content": content},
        ]

    monkeypatch.setattr(loop_module, "_append_tool_result", broken_append)
    with pytest.raises(AssertionError, match="exact tool-result payload"):
        loop_module.run_agent("inspect", generate, workspace)


def test_capstone_is_learner_only_and_stale_evaluator_is_fully_removed():
    assert CAPSTONE_CLI.is_file()
    source = CAPSTONE_CLI.read_text(encoding="utf-8")
    tree = ast.parse(source)
    assert "tiny_llm_ref" not in source
    assert "--solution" not in source
    assert "importlib" not in source
    assert {
        node.name
        for node in tree.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        and not node.name.startswith("_")
    } == {"run_capstone", "main"}

    project = (ROOT / "pyproject.toml").read_text(encoding="utf-8")
    assert "week4-capstone" in project
    assert "evaluate-agent" not in project
    assert not STALE_EVALUATOR.exists()
    assert not STALE_EVALS.exists()
